solutionCodeJson.code:
// Bài 13.2 — xếp loại: kiểm đầu vào trước, rồi các mốc từ cao xuống thấp, đều dùng >=
function grade(score) {
  // !(a && b) bắt cả NaN: mọi phép so với NaN đều false
  if (!(score >= 0 && score <= 10)) throw new RangeError('score must be between 0 and 10');
  if (score >= 8.5) return 'A';
  if (score >= 7) return 'B';
  if (score >= 5.5) return 'C';
  if (score >= 4) return 'D';
  return 'F';
}

